import React, { useState, useEffect } from 'react';
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION
// ==========================================
const DATA_BASE_URL = '.';
const CSV_FILE = 'forecast_outputs.csv';
const TXT_FILE = 'lime_short_sentences.txt';

const RiverDashboard = () => {
  const [forecastData, setForecastData] = useState([]);
  const [limeDetails, setLimeDetails] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // Helper: Parse CSV
  const parseCSV = (csvText) => {
    const lines = csvText.split('\n').filter(line => line.trim() !== '');
    if (lines.length < 2) return []; 
    const headers = lines[0].split(',').map(h => h.trim());
    const data = [];
    for (let i = 1; i < lines.length; i++) {
        const values = lines[i].split(',');
        if (values.length === headers.length) {
            let rowObject = {};
            for (let j = 0; j < headers.length; j++) {
                rowObject[headers[j]] = values[j].trim();
            }
            data.push(rowObject);
        }
    }
    return data;
  };

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        // Fetch CSV
        const csvRes = await fetch(`${DATA_BASE_URL}/${CSV_FILE}`);
        if (!csvRes.ok) throw new Error('Failed to fetch forecast data');
        const csvText = await csvRes.text();
        setForecastData(parseCSV(csvText));

        // Fetch LIME Text
        const txtRes = await fetch(`${DATA_BASE_URL}/${TXT_FILE}`);
        if (!txtRes.ok) throw new Error('Failed to fetch analysis data');
        const txtText = await txtRes.text();
        setLimeDetails(txtText.split('\n').filter(line => line.trim() !== ''));

      } catch (err) {
        console.error("Data Load Error:", err);
        setError("Unable to load dashboard data. Please check connection.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  if (isLoading) return <div className="dashboard-loading">Initializing Dashboard...</div>;
  if (error) return <div className="dashboard-error">{error}</div>;

  const tableHeaders = forecastData.length > 0 ? Object.keys(forecastData[0]) : [];
  
  // Determine Status (Logic can be expanded based on real data)
  // Hardcoded for now based on your previous design
  const currentStatus = "Normal"; 
  const statusClass = currentStatus === "Normal" ? "status-normal" : "status-warning";

  return (
    <div className="dashboard">
      <header className="aiiot-header">
              <div style={{ maxWidth: '80rem', margin: '0 auto', padding: '0 1.5rem', position: 'relative' }}>
                <nav style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', height: '5rem' }}>
                  
                  {/* LOGO */}
                  <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '1rem', textDecoration: 'none', zIndex: 1001 }}>
                    <div className="logo-box">
                      <img src="/logo/logo.png" alt="Adi Shankara Institute" style={{ height: '100%', width: 'auto' }} />
                    </div>
                    <div style={{ display: 'flex', flexDirection: 'column' }}>
                      <span style={{ fontSize: '1.25rem', fontWeight: 700, color: '#1e293b', lineHeight: 1.2 }}>AI-IoT Innovations</span>
                      {/* <span style={{ fontSize: '0.75rem', color: '#64748b', fontWeight: 500 }}>Adi Shankara Engineering Institute</span> */}
                    </div>
                  </Link>
      
                  {/* DESKTOP NAV */}
                  <div className="desktop-nav">
                    <a href="#about" className="nav-link">About</a>
                    <a href="#projects" className="nav-link">Solutions</a>
      
                    <Link to="/resources" className="nav-link"> R&D</Link>
                    <a href="#team" className="nav-link">Team</a>
                    {/* === MEGA MENU IMPLEMENTATION === */}
                    <div 
                      className="mega-menu-wrapper"
                      onMouseEnter={() => setIsMegaMenuOpen(true)}
                      onMouseLeave={() => setIsMegaMenuOpen(false)}
                    >
                      <Link to="" className="nav-link product-trigger">
                        Products <span>▾</span>
                      </Link>
      
                      <div className={`mega-menu-container ${isMegaMenuOpen ? 'visible' : ''}`}>
                        {/* LEFT SIDEBAR (Categories) */}
                        <div className="mega-menu-sidebar">
                          {Object.keys(productMenuData).map((key) => (
                            <div 
                              key={key} 
                              className={`mega-sidebar-item ${activeCategory === key ? 'active' : ''}`}
                              onMouseEnter={() => setActiveCategory(key)}
                            >
                              {key} <span>›</span>
                            </div>
                          ))}
                        </div>
      
                        {/* RIGHT CONTENT (Grid) */}
                        <div className="mega-menu-content">
                          <div className="mega-content-header">
                            <h4>{productMenuData[activeCategory].title}</h4>
                            <p>{productMenuData[activeCategory].description}</p>
                          </div>
                          <div className="mega-grid">
                            {productMenuData[activeCategory].items.map((item, idx) => (
                              <Link to={item.link} key={idx} className="mega-product-card">
                                 <div className="mega-img-box">
                                   <img src={item.image} alt={item.name} />
                                 </div>
                                 <span>{item.name}</span>
                              </Link>
                            ))}
                          </div>
                        </div>
                      </div>
                    </div>
                    {/* === END MEGA MENU === */}
      
                    <Link to="/homepage" className="nav-link">AirAware</Link>
                    <a href="/weather-home" className="nav-link">AWS</a>
                    <a href="#footer" className="nav-btn-primary">Get in Touch</a>
                  </div>
      
                  {/* MOBILE HAMBURGER BUTTON */}
                  <button className="mobile-nav-toggle" onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
                    {isMobileMenuOpen ? '✕' : '☰'}
                  </button>
                </nav>
              </div>
      
              {/* MOBILE MENU CONTENT */}
              {isMobileMenuOpen && (
                <div className="mobile-menu-wrapper">
                  <a href="#about" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9', textDecoration:'none' }}>About</a>
                  <a href="#team" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9', textDecoration:'none' }}>Team</a>
                  <Link to="/resources" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9', textDecoration: 'none' }}>Resources</Link>
                  <a href="#projects" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9', textDecoration: 'none' }}>Solutions</a>
                  {/* REPLACING the simple Products Link with this Dropdown Logic */}
                  <div style={{ borderBottom: '1px solid #f1f5f9', paddingBottom: '0.5rem' }}>
                    <div 
                      onClick={() => setMobileProductExpanded(!mobileProductExpanded)}
                      style={{ 
                        display: 'flex', 
                        justifyContent: 'space-between', 
                        alignItems: 'center',
                        padding: '1rem 0', 
                        fontSize: '1.1rem', 
                        fontWeight: 600, 
                        color: '#1e293b', 
                        cursor: 'pointer' 
                      }}
                    >
                      Products <span>{mobileProductExpanded ? '▴' : '▾'}</span>
                    </div>
      
                    {/* The Dropdown Content */}
                    {mobileProductExpanded && (
                      <div style={{ background: '#f8fafc', padding: '1rem', borderRadius: '8px' }}>
                        {Object.keys(productMenuData).map((categoryKey) => (
                          <div key={categoryKey} style={{ marginBottom: '1rem' }}>
                            <h5 style={{ fontSize: '0.85rem', color: '#3b82f6', textTransform: 'uppercase', marginBottom: '0.5rem' }}>
                              {categoryKey}
                            </h5>
                            {productMenuData[categoryKey].items.map((item, i) => (
                              <Link 
                                key={i} 
                                to={item.link} 
                                onClick={() => setIsMobileMenuOpen(false)}
                                style={{ display: 'block', padding: '0.25rem 0', fontSize: '0.95rem', color: '#475569', textDecoration: 'none' }}
                              >
                                • {item.name}
                              </Link>
                            ))}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                  <Link to="/homepage" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9', textDecoration: 'none' }}>
                  </Link>
                  <a href="/weather-home" onClick={() => setIsMobileMenuOpen(false)} style={{ display: 'block', padding: '1rem 0', fontSize: '1.1rem', fontWeight: 600, color: '#1e293b', borderBottom: '1px solid #f1f5f9', textDecoration: 'none' }}>AWS</a>
                </div>
              )}
            </header>
      {/* HEADER */}
      {/* <header className="dashboard-header">
        <div className="header-content">
          <h1>Periyar River Monitor</h1>
          <p className="last-updated">System Updated: 8/08/24</p>
        </div>
      </header> */}

      <div className="dashboard-grid">
        
        {/* CARD 1: HERO METRIC (Current Water Level) */}
        <div className="card current-level-card">
          <h2>
            <span>Current Status</span>
          </h2>
          <div className="level-display-container">
              <div className="level-value-box">
                  <span className="value">1.41</span>
                  <span className="unit">meters</span>
              </div>
              
              <div className={`level-status-indicator ${statusClass}`}>
                  <span className="status-dot"></span>
                  {currentStatus} Conditions
              </div>

              <div className="level-date">
                  <span className="label">Measured on:</span> 8/08/24
              </div>
          </div>
        </div>

        {/* CARD 2: FORECAST GRID */}
        <div className="card forecast-section">
            <h2>
              <span>6-Hour Forecast</span>
            </h2>

            {forecastData.length > 0 ? (
            <div className="forecast-grid">
              {forecastData.map((row, rowIndex) => (
                <div key={rowIndex} className="forecast-item-card">
                    {tableHeaders.map((header, colIndex) => (
                    <div key={colIndex} className="forecast-detail">
                        <span className="detail-label">{header.replace(/_/g, " ")}</span>
                        <span className="detail-value">{row[header]}</span>
                    </div>
                    ))}
                </div>
              ))}
            </div>
            ) : (
            <p className="no-data">No forecast data available.</p>
            )}
        </div>

        {/* CARD 3: AI INSIGHTS (LIME) */}
        <div className="card lime-card">
          <h2>
            <span>AI Risk Analysis (LIME)</span>
          </h2>
          {limeDetails.length > 0 ? (
            <ul className="lime-list">
                {limeDetails.map((detail, index) => (
                    <li key={index}>{detail}</li>
                ))}
            </ul>
          ) : (
              <p>No analysis details available.</p>
          )}
        </div>

      </div>

      <footer className="dashboard-footer">
        <p>&copy; 2024 Periyar River Monitoring Authority | Intelligent Water Systems</p>
      </footer>
    </div>
  );
};

export default RiverDashboard;
